        [nums[i], nums[i + 1]] = [nums[i + 1], nums[i]];
    }
    return nums;
}

impl Solution {
    pub fn number_game(nums: Vec<i32>) -> Vec<i32> {
        let mut nums = nums;
        nums.sort_unstable();
        for i in (0..nums.len()).step_by(2) {
            nums.swap(i, i + 1);
        }
        nums
    }
}

class Solution {
public:
    vector<int> numberGame(vector<int>& nums) {
        priority_queue<int, vector<int>, greater<int>> pq;
        vector<int> ans;

        for(auto i:nums){
            pq.push(i);
        }

        while(!pq.empty()){
            int alice=pq.top();
            pq.pop();
            int bob=pq.top();
            pq.pop();
            ans.push_back(bob);
            ans.push_back(alice);
        }

        return ans;
    }
